class Solution {
  static final long MOD = 1_000_000_007L;
  int[] ys, count;
  long[] covered;

  void update(int node, int lo, int hi, int ql, int qr, int delta) {
    if (ql >= hi || qr <= lo) return;
    if (ql <= lo && hi <= qr) count[node] += delta;
    else {
      int mid = (lo + hi) >>> 1;
      update(node * 2, lo, mid, ql, qr, delta);
      update(node * 2 + 1, mid, hi, ql, qr, delta);
    }
    if (count[node] > 0) covered[node] = ys[hi] - ys[lo];
    else if (hi - lo == 1) covered[node] = 0;
    else covered[node] = covered[node * 2] + covered[node * 2 + 1];
  }

  public int rectangleArea(int[][] rectangles) {
    int n = rectangles.length;
    ys = new int[2 * n];
    for (int i = 0; i < n; i++) {
      ys[2 * i] = rectangles[i][1];
      ys[2 * i + 1] = rectangles[i][3];
    }
    java.util.Arrays.sort(ys);
    int m = 0;
    for (int y : ys) if (m == 0 || ys[m - 1] != y) ys[m++] = y;
    java.util.List<int[]> ev = new java.util.ArrayList<>();
    for (int[] r : rectangles) {
      int a = java.util.Arrays.binarySearch(ys, 0, m, r[1]),
          b = java.util.Arrays.binarySearch(ys, 0, m, r[3]);
      ev.add(new int[] {r[0], a, b, 1});
      ev.add(new int[] {r[2], a, b, -1});
    }
    ev.sort(java.util.Comparator.comparingInt(e -> e[0]));
    count = new int[4 * m + 5];
    covered = new long[4 * m + 5];
    long area = 0;
    int prev = ev.get(0)[0];
    for (int[] e : ev) {
      area = (area + covered[1] * (e[0] - prev)) % MOD;
      update(1, 0, m - 1, e[1], e[2], e[3]);
      prev = e[0];
    }
    return (int) area;
  }
}
